'use client';
import {useEffect,useRef,useState,lazy,Suspense} from 'react';
import {House,LayoutDashboard,Plus,MapPin,Layers,Box,Leaf,Wallet,BookOpen,FolderOpen,ShieldCheck,LogOut,ChevronRight,ArrowUpRight,Download,Save,Check,Menu,X,Clock,MessageCircle,Sun,Compass,ArrowLeft,Search,User,Share2,Settings,HelpCircle,TriangleAlert} from 'lucide-react';
